package dev.veltraph.client.navigation;
import dev.veltraph.client.rotation.DirectRotationPublicationIdentity;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LegacyRetiredParentInteractionIdentityTest {
 final Object root=new Object(),parent=new Object(),p=new Object(),w=new Object(),c=new Object(),config=new Object(),service=new Object();
 LegacyTravelPublicationIdentity.State state(long g,long e,long s,long revision,boolean usable){return new LegacyTravelPublicationIdentity.State(root,parent,parent,parent,p,w,c,config,revision,1,service,g,e,s,null,true,true,usable);}
 DirectRotationPublicationIdentity.Scope scope(long g,long e,long s){return new DirectRotationPublicationIdentity.Scope(root,parent,parent,parent,p,w,c,config,service,g,e,s,1);}
 LegacyRetiredParentInteractionIdentity.Lease proof(){return LegacyRetiredParentInteractionIdentity.Lease.capture(state(4,9,20,3,true),7,1);}
 DirectRotationPublicationIdentity.Proof own(){return new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(6,10,21),21,DirectRotationPublicationIdentity.Mode.TRACK);}
 @Test void actualOwnTrackAdvancesOnlyItsExactBeforeAndAfter(){var x=proof();assertTrue(x.current(state(4,9,20,3,true),true,7));assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));assertTrue(x.current(state(6,10,21,3,true),true,7));assertFalse(x.current(state(4,9,20,3,true),true,7));}
 @Test void ownInProgressGenerationIsVetoOnlyAndCannotRenewOutsideReceipt(){var x=proof();assertFalse(x.current(state(6,9,20,3,true),true,7));assertTrue(x.publicationFence(state(6,9,20,3,true),true,7));assertEquals(4,x.generation());assertFalse(x.publicationFence(state(6,9,20,3,true),true,9));}
 @Test void noEffectNewLegAdmissionRetirementRevokesEveryReadAndOwnAdvance(){var x=proof();assertFalse(x.current(state(4,9,20,3,true),true,9));assertFalse(x.cleanupCurrent(state(4,9,20,3,true),true,9));assertFalse(x.publicationFence(state(6,9,20,3,true),true,9));assertFalse(x.advance(own(),true,state(6,10,21,3,true),true,9));}
 @Test void rawCurrentFieldsAndLateBeforeCannotBecomeOwnTransition(){var x=proof();assertFalse(x.current(state(6,10,21,3,true),true,7));var late=new DirectRotationPublicationIdentity.Proof(scope(5,9,20),scope(7,10,21),21,DirectRotationPublicationIdentity.Mode.TRACK);assertFalse(x.advance(late,true,state(7,10,21,3,true),true,7));assertEquals(4,x.generation());assertEquals(20,x.serial());}
 @Test void unknownSkippedPublicationOrWrongGenerationSpanIsRefused(){var x=proof();var jump=new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(6,10,22),22,DirectRotationPublicationIdentity.Mode.TRACK);assertFalse(x.advance(jump,true,state(6,10,22,3,true),true,7));var span=new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(7,10,21),21,DirectRotationPublicationIdentity.Mode.TRACK);assertFalse(x.advance(span,true,state(7,10,21,3,true),true,7));}
 @Test void sameTickRetentionRequiresItsPreviousActualOwnTicket(){var x=proof();var skip=new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(5,9,20),20,DirectRotationPublicationIdentity.Mode.SAME_TICK_TRACK);assertFalse(x.advance(skip,false,state(5,9,20,3,true),true,7));assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));var retained=new DirectRotationPublicationIdentity.Proof(scope(6,10,21),scope(7,10,21),21,DirectRotationPublicationIdentity.Mode.SAME_TICK_TRACK);assertTrue(x.advance(retained,false,state(7,10,21,3,true),true,7));}
 @Test void factoryMaySeedOnlyAuthenticCurrentOwnScopeThenRetainIt(){var x=proof();var prior=new DirectRotationPublicationIdentity.Proof(scope(2,9,19),scope(4,9,20),20,DirectRotationPublicationIdentity.Mode.TRACK);assertTrue(x.seedOwn(prior,false));var retained=new DirectRotationPublicationIdentity.Proof(scope(4,9,20),scope(5,9,20),20,DirectRotationPublicationIdentity.Mode.SAME_TICK_TRACK);assertTrue(x.advance(retained,false,state(5,9,20,3,true),true,7));assertFalse(proof().seedOwn(own(),false));}
 @Test void sameStorePolicyRevocationAllowsOnlyExactCleanup(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));var revoked=state(6,10,21,5,false);assertFalse(x.current(revoked,true,7));assertFalse(x.publicationFence(revoked,true,7));assertTrue(x.cleanupCurrent(revoked,true,7));assertFalse(x.cleanupCurrent(state(7,10,21,5,false),true,7));}
 @Test void disabledAbsentParentIsCleanupOnlyAndNeverForeignOrReplacement(){var x=proof();var absent=new LegacyTravelPublicationIdentity.State(root,parent,null,null,p,w,c,config,5,1,service,4,9,20,null,true,false,false);assertTrue(x.cleanupCurrent(absent,true,7));assertFalse(x.current(absent,true,7));assertFalse(x.cleanupCurrent(absent,false,7));var foreign=new LegacyTravelPublicationIdentity.State(root,parent,new Object(),null,p,w,c,config,5,1,service,4,9,20,null,true,false,false);assertFalse(x.cleanupCurrent(foreign,true,7));}
 @Test void activeLegForeignPwcAndStoreCannotUseInteractionProof(){var x=proof();var active=new LegacyTravelPublicationIdentity.State(root,parent,parent,parent,p,w,c,config,3,1,service,4,9,20,new Object(),true,true,true);assertFalse(x.current(active,true,7));var foreign=new LegacyTravelPublicationIdentity.State(root,parent,parent,parent,p,new Object(),c,config,3,1,service,4,9,20,null,true,true,true);assertFalse(x.cleanupCurrent(foreign,true,7));}
 @Test void callbackAfterReceiptObservationCannotAdoptNewPrivateAdmissionVersion(){var x=proof();long[] version={7};var live=state(6,10,21,3,true);Runnable callback=()->{var middle=LegacyTravelPublicationIdentity.Lease.admit(live,live,new Object(),version[0],version[0]);assertNotNull(middle);version[0]++;middle.closed();version[0]++;};callback.run();assertFalse(x.advance(own(),true,live,true,version[0]));assertEquals(4,x.generation());assertEquals(9,x.epoch());assertEquals(20,x.serial());}
 @Test void callbackReplacedActualServiceGenerationCannotAdoptOldOpaqueAfterScope(){var x=proof();assertFalse(x.advance(own(),true,state(7,10,21,3,true),true,7));assertEquals(4,x.generation());}
 @Test void callbackChangedActualRosterCannotPassFinalReadOrAdvance(){var x=proof();assertFalse(x.publicationFence(state(6,9,20,3,true),false,7));assertFalse(x.advance(own(),true,state(6,10,21,3,true),false,7));assertEquals(20,x.serial());}
 @Test void actualOwnCancellationAdvancesCleanupOnlyAndCannotRepublish(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));assertTrue(x.advanceCleanup(scope(6,10,21),scope(7,11,21),21,state(7,11,21,3,true),true,7));assertTrue(x.cleanupCurrent(state(7,11,21,3,true),true,7));assertFalse(x.current(state(7,11,21,3,true),true,7));assertFalse(x.publicationFence(state(8,11,21,3,true),true,7));assertFalse(x.advanceCleanup(scope(7,11,21),scope(8,12,21),21,state(8,12,21,3,true),true,7));}
 @Test void noOwnCameraCannotManufactureCancellation(){var x=proof();assertFalse(x.advanceCleanup(scope(4,9,20),scope(5,10,20),20,state(5,10,20,3,true),true,7));assertEquals(4,x.generation());assertFalse(x.cancelled());assertTrue(x.cleanupCurrent(state(4,9,20,3,true),true,7));}
 @Test void sameStorePolicyRevocationCanConsumeOnlyActualOwnCancellation(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));assertTrue(x.advanceCleanup(scope(6,10,21),scope(7,11,21),21,state(7,11,21,9,false),true,7));assertTrue(x.cleanupCurrent(state(7,11,21,9,false),true,7));assertFalse(x.current(state(7,11,21,9,false),true,7));}
 @Test void foreignNewRequestAfterCancelCannotBecomeCleanup(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));assertFalse(x.advanceCleanup(scope(6,10,21),scope(7,11,21),21,state(8,11,21,3,true),true,7));assertEquals(6,x.generation());assertFalse(x.cancelled());}
 @Test void callbackNoEffectAdmissionAfterCancelRevokesConsumption(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));long[] version={7};Runnable callback=()->{version[0]++;version[0]++;};callback.run();assertFalse(x.advanceCleanup(scope(6,10,21),scope(7,11,21),21,state(7,11,21,3,true),true,version[0]));assertFalse(x.cancelled());}
 @Test void callbackForeignRosterAfterCancelRejectsAndKeepsOldExpectedStamp(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));assertFalse(x.advanceCleanup(scope(6,10,21),scope(7,11,21),21,state(7,11,21,3,true),false,7));assertEquals(10,x.epoch());assertFalse(x.cancelled());}
 @Test void wrongTicketOrEpochSpanCannotCertifyCancellation(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));assertFalse(x.advanceCleanup(scope(6,10,21),scope(7,12,21),21,state(7,12,21,3,true),true,7));assertFalse(x.advanceCleanup(scope(6,10,21),scope(7,11,22),22,state(7,11,22,3,true),true,7));assertFalse(x.cancelled());}
 @Test void typedDisabledAbsentOriginalParentSupportsCancellationOnly(){var x=proof();assertTrue(x.advance(own(),true,state(6,10,21,3,true),true,7));var a=new DirectRotationPublicationIdentity.Scope(root,parent,null,null,p,w,c,config,service,6,10,21,9);var b=new DirectRotationPublicationIdentity.Scope(root,parent,null,null,p,w,c,config,service,7,11,21,9);var live=new LegacyTravelPublicationIdentity.State(root,parent,null,null,p,w,c,config,9,1,service,7,11,21,null,true,false,false);assertTrue(x.advanceCleanup(a,b,21,live,true,7));assertTrue(x.cleanupCurrent(live,true,7));assertFalse(x.current(live,true,7));}
}

